    sortingOptions,
    columns: TASK_RUN_SORT_COLUMNS,
    defaultSorting: DEFAULT_SORTING,
    onSortingOptionsChange,
  });

  const handleRowActivate = useCallback(
    (row: Row<TaskRun>) => {
      navigate(Urls.monitorTaskRunDetails(row.original.id));
    },
    [navigate],
  );

  const treeTableInstance = useTreeTableInstance<TaskRun>({
    data: taskRuns,
    columns,
    sorting: sortingState,
    manualSorting: true,
    getNodeId: (taskRun) => String(taskRun.id),
    onRowActivate: handleRowActivate,
    onSortingChange,
  });

  useScrollToTop({
    ref: treeTableInstance.containerRef,
    keys: [page, sortingOptions],
    skip: isFetching,
  });

cy.findByRole("link", { name: "Runs" }).click();
cy.location("pathname").should("eq", "/monitor/tasks/runs");
cy.wait("@getTaskRuns");
cy.findByTestId("task-runs-table")
  .findAllByTestId("task-run")
  .should("have.length", 1);
